import{_ as i,c as e,a as t,o as a}from"./app-PgcbWxun.js";const s={};function n(r,l){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="skills-rules" tabindex="-1"><a class="header-anchor" href="#skills-rules"><span>Skills Rules</span></a></h1><h2 id="_1-配图规范" tabindex="-1"><a class="header-anchor" href="#_1-配图规范"><span>1. 配图规范</span></a></h2><p>在画图时，请检查图片布局的合理性：</p><ul><li>文字和图片等内容都不要有重叠</li><li>一行一列都要对齐，保持方正</li><li>使用统一的格子大小和坐标系</li><li>title 在各自的范围内居中排布</li><li>底部文字和上面内容的距离要合理，不要留太多空白</li></ul><h2 id="_2-图片宽度规范" tabindex="-1"><a class="header-anchor" href="#_2-图片宽度规范"><span>2. 图片宽度规范</span></a></h2><p>在文章中引用图片时：</p><ul><li>如果图的高度与宽度的比值 &gt; 0.5（即图比较&quot;高&quot;），使用 <code>=560x</code></li><li>如果图的高度与宽度的比值 ≤ 0.5（即图比较&quot;扁&quot;），不加宽度约束</li></ul><h2 id="_3-写作规范" tabindex="-1"><a class="header-anchor" href="#_3-写作规范"><span>3. 写作规范</span></a></h2><p>写内容时，要像给初中生讲故事一样，要有叙事性，但要遵循两个原则：</p><p><strong>原则一：简洁</strong></p><ul><li>提纲挈领，不能啰嗦</li><li>举一个例子就能理解的，就不要举好几个例子</li><li>能用一句话说清楚的，就不要用两句话</li></ul><p><strong>原则二：正确</strong></p><ul><li>必须要确保写的内容是对的</li><li>不确定的内容要给用户反馈，而不是瞎写</li><li>引用论文或数据时，要标注来源</li></ul><p><strong>叙事性要求：</strong></p><ul><li>用讲故事的方式引入概念，让读者理解&quot;为什么需要这个&quot;</li><li>比喻要恰当，但不要把比喻直接写进正文（比如&quot;SiLU是一把锄头&quot;）</li><li>比喻是用来帮助理解的，不是用来定义概念的</li></ul>',15)])])}const u=i(s,[["render",n]]),c=JSON.parse('{"path":"/AGENTS.html","title":"Skills Rules","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"1. 配图规范","slug":"_1-配图规范","link":"#_1-配图规范","children":[]},{"level":2,"title":"2. 图片宽度规范","slug":"_2-图片宽度规范","link":"#_2-图片宽度规范","children":[]},{"level":2,"title":"3. 写作规范","slug":"_3-写作规范","link":"#_3-写作规范","children":[]}],"git":{"createdTime":null,"updatedTime":null,"contributors":[]},"filePathRelative":"AGENTS.md"}');export{u as comp,c as data};
